$buscar=trim((string)($_GET['buscar']??''));$desde=(string)($_GET['desde']??'');$hasta=(string)($_GET['hasta']??'');$pagina=max(1,(int)($_GET['pagina']??1));$limite=8;$offset=($pagina-1)*$limite;$cond=[];$params=[];if($buscar!==''){$cond[]='(c.nombre LIKE ? OR i.codigo_qr LIKE ? OR i.tipo LIKE ?)';$params=array_fill(0,3,'%'.$buscar.'%');}if(fecha_valida($desde)){$cond[]='v.fecha>=?';$params[]=$desde.' 00:00:00';}if(fecha_valida($hasta)){$cond[]='v.fecha<=?';$params[]=$hasta.' 23:59:59';}$where=$cond?' WHERE '.implode(' AND ',$cond):'';$s=$db->prepare('SELECT COUNT(*) FROM venta v INNER JOIN cliente c ON c.id_cliente=v.id_cliente LEFT JOIN instrumento i ON i.id_instrumento=v.id_instrumento'.$where);$s->execute($params);$total_registros=(int)$s->fetchColumn();$s=$db->prepare('SELECT v.*,c.nombre AS cliente_nombre,i.codigo_qr,i.tipo FROM venta v INNER JOIN cliente c ON c.id_cliente=v.id_cliente LEFT JOIN instrumento i ON i.id_instrumento=v.id_instrumento'.$where.' ORDER BY v.fecha DESC,v.id_venta DESC LIMIT '.$limite.' OFFSET '.$offset);$s->execute($params);$ventas=$s->fetchAll();$clientes=$db->query('SELECT id_cliente,nombre FROM cliente ORDER BY nombre')->fetchAll();$instrumentos=$db->query('SELECT id_instrumento,codigo_qr,tipo FROM instrumento ORDER BY codigo_qr')->fetchAll();$titulo='Ventas';require __DIR__.'/../../includes/header.php';?>
